import React, { useState } from 'react';
import booksData from '../../data/Books.json';
import BookCard from './BookCard/BookCard';
import Filters from '../Filters/Filters';
import './BooksList.css';
const searchTerm = "назва_книги"
function BooksList({ searchTerm }) {
    const [filters, setFilters] = useState({ price: '', pages: '', genre: '' });

    const handleFilterChange = (selectedFilters) => {
        setFilters(selectedFilters);
    };

    console.log("Received searchTerm:", searchTerm); // Перевірка значення searchTerm

    const filteredBooks = booksData.filter((book) => {
        const priceMatch = filters.price ? book.price <= Number(filters.price) : true;
        const pagesMatch = filters.pages ? book.pages <= Number(filters.pages) : true;
        const genreMatch = filters.genre
            ? Array.isArray(book.genre)
                ? book.genre.includes(filters.genre)
                : book.genre === filters.genre
            : true;

        const searchMatch = searchTerm 
            ? book.title.toLowerCase().includes(searchTerm.toLowerCase().trim()) 
            : true;

        console.log("Checking book:", book.title, "| searchMatch:", searchMatch); // Перевірка відповідності пошуку

        return priceMatch && pagesMatch && genreMatch && searchMatch;
    });

    return (
        <div>
            <Filters onFilterChange={handleFilterChange} />

            <div className="books-list">
                {filteredBooks.length === 0 ? (
                    <p>Книги не знайдено</p> // Повідомлення, якщо книги не знайдено
                ) : (
                    filteredBooks.map((book) => (
                        <BookCard
                            key={book.id}
                            id={book.id}
                            name={book.title}
                            pages={book.pages}
                            genre={book.genre}
                            image={book.image}
                            price={book.price}
                            description={book.description}
                        />
                    ))
                )}
            </div>
        </div>
    );
}

export default BooksList;
